CREATE OR REPLACE FUNCTION private.require_vendor_session(p_session_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_store_id uuid;
  v_token_hash bytea;
begin
  if coalesce(length(p_session_token), 0) < 32 then
    raise exception 'VENDOR_SESSION_INVALID'
      using errcode = '28000';
  end if;

  v_token_hash := digest(
    p_session_token,
    'sha256'
  );

  select s.store_id
  into v_store_id
  from public.vendor_sessions s
  join public.local_stores ls
    on ls.id = s.store_id
  where s.token_hash = v_token_hash
    and s.revoked_at is null
    and s.expires_at > now()
    and lower(
      trim(coalesce(ls.status, ''))
    ) = 'active'
  limit 1;

  if v_store_id is null then
    raise exception 'VENDOR_SESSION_INVALID'
      using errcode = '28000';
  end if;

  update public.vendor_sessions
  set last_seen_at = now()
  where token_hash = v_token_hash;

  return v_store_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_login(p_identity text, p_password text)
 RETURNS TABLE(id uuid, store_name text, logo_url text, username text, phone text, country text, governorate text, store_type text, specialty text, default_currency text, commission_rate numeric, status text, exchange_rate numeric, exchange_base_currency text, exchange_target_currency text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_store RECORD;
    v_stored_password TEXT;
    v_password_ok BOOLEAN := FALSE;
BEGIN
    -- البحث باسم المستخدم أو رقم الهاتف (مع تجاهل المسافات)
    SELECT s.* INTO v_store
    FROM public.local_stores s
    WHERE (TRIM(s.username) = TRIM(p_identity) OR TRIM(s.phone) = TRIM(p_identity))
      AND LOWER(s.status) = 'active'
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN;
    END IF;

    v_stored_password := COALESCE(v_store.password_hash, '');

    -- 1. مطابقة نصية صريحة (Plain Text) - لكل المتاجر المضافة من لوحة الأدمن
    IF v_stored_password = p_password THEN
        v_password_ok := TRUE;
    END IF;

    -- 2. مطابقة تشفير bcrypt (إذا كانت كلمة المرور مشفرة)
    IF NOT v_password_ok AND v_stored_password LIKE '$2%' THEN
        BEGIN
            IF crypt(p_password, v_stored_password) = v_stored_password THEN
                v_password_ok := TRUE;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_password_ok := FALSE;
        END;
    END IF;

    -- 3. مطابقة تشفير SHA256 (إن وجد)
    IF NOT v_password_ok THEN
        IF LOWER(v_stored_password) = LOWER(ENCODE(DIGEST(p_password, 'sha256'), 'hex')) THEN
            v_password_ok := TRUE;
        END IF;
    END IF;

    IF NOT v_password_ok THEN
        RETURN;
    END IF;

    -- إرجاع بيانات المتجر
    RETURN QUERY
    SELECT 
        v_store.id,
        v_store.store_name,
        v_store.logo_url,
        v_store.username,
        v_store.phone,
        v_store.country,
        v_store.governorate,
        v_store.store_type,
        v_store.specialty,
        v_store.default_currency,
        v_store.commission_rate,
        v_store.status,
        v_store.exchange_rate,
        v_store.exchange_base_currency,
        v_store.exchange_target_currency;
END;
$function$

CREATE OR REPLACE FUNCTION public.vendor_login_session(p_identity text, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_store_id uuid;
  v_store public.local_stores%rowtype;
  v_token text;
  v_expires_at timestamptz := now() + interval '12 hours';
begin
  if trim(coalesce(p_identity, '')) = ''
     or coalesce(p_password, '') = '' then
    raise exception 'بيانات الدخول غير مكتملة'
      using errcode = '28000';
  end if;

  -- استخدام دالة الدخول القديمة المستقرة للتحقق من الحساب.
  select authenticated_store.id
  into v_store_id
  from public.vendor_login(
    trim(p_identity),
    p_password
  ) authenticated_store
  limit 1;

  if v_store_id is null then
    raise exception 'بيانات الدخول غير صحيحة أو المتجر غير نشط'
      using errcode = '28000';
  end if;

  select s.*
  into v_store
  from public.local_stores s
  where s.id = v_store_id
    and lower(trim(coalesce(s.status, ''))) = 'active'
  limit 1;

  if v_store.id is null then
    raise exception 'بيانات الدخول غير صحيحة أو المتجر غير نشط'
      using errcode = '28000';
  end if;

  -- تنظيف الجلسات المنتهية أو الملغاة.
  delete from public.vendor_sessions
  where expires_at <= now()
     or revoked_at is not null;

  -- إنشاء رمز جلسة آمن.
  v_token := encode(gen_random_bytes(32), 'hex');

  insert into public.vendor_sessions(
    store_id,
    token_hash,
    expires_at
  )
  values (
    v_store.id,
    digest(v_token, 'sha256'),
    v_expires_at
  );

  return jsonb_build_object(
    'session_token', v_token,
    'expires_at', v_expires_at,
    'store', jsonb_build_object(
      'id', v_store.id,
      'store_name', v_store.store_name,
      'logo_url', v_store.logo_url,
      'username', v_store.username,
      'phone', v_store.phone,
      'country', v_store.country,
      'governorate', v_store.governorate,
      'store_type', v_store.store_type,
      'specialty', v_store.specialty,
      'default_currency', v_store.default_currency,
      'commission_rate', v_store.commission_rate,
      'status', v_store.status,
      'exchange_rate', v_store.exchange_rate,
      'exchange_base_currency',
        v_store.exchange_base_currency,
      'exchange_target_currency',
        v_store.exchange_target_currency
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.vendor_logout_session(p_session_token text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
declare
  v_token_hash bytea;
begin
  if coalesce(p_session_token, '') = '' then
    return;
  end if;

  v_token_hash := digest(
    p_session_token,
    'sha256'
  );

  update public.vendor_sessions
  set revoked_at = coalesce(
    revoked_at,
    now()
  )
  where token_hash = v_token_hash;
end;
$function$
